const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;
const W=24,H=16,T=32,plots=[];for(let y=6;y<12;y++)for(let x=6;x<14;x++)plots.push({x,y,tilled:false,crop:null,progress:0,watered:false});
const types={turnip:{name:'nabo lunar',price:7,sell:9,grow:34,color:'#dbe3c5'},nightflower:{name:'flor nocturna',price:10,sell:14,grow:48,color:'#c78ec3'}};
let data={day:1,coins:12,harvest:0,turnipSeeds:5,flowerSeeds:3,turnipInv:0,flowerInv:0,appleInv:0,questDone:false,selectedSeed:'turnip',tool:'hoe',player:{x:10,y:13},played:0};
try{const saved=JSON.parse(localStorage.getItem('midnightGardenSave'));if(saved){data={...data,...saved,player:{...data.player,...saved.player}};if(saved.plots?.length)plots.forEach((p,i)=>Object.assign(p,saved.plots[i]||{}))}}catch(e){}
let toastTimer=0,dirty=0,last=performance.now(),keys={},selectedPlot=null;
const $=id=>document.getElementById(id), clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function save(){try{localStorage.setItem('midnightGardenSave',JSON.stringify({...data,plots}))}catch(e){}}
function say(text){const el=$('toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function ui(){ $('coins').textContent=data.coins;$('harvestCount').textContent=data.harvest;$('dayNum').textContent=String(data.day).padStart(2,'0');$('turnipQty').textContent=data.turnipSeeds;$('flowerQty').textContent=data.flowerSeeds;$('turnipInv').textContent=data.turnipInv;$('flowerInv').textContent=data.flowerInv;$('appleInv').textContent=data.appleInv;
const n=data.turnipInv+data.flowerInv+data.appleInv;$('basketTag').textContent=n?`${n} cosecha${n===1?'':'s'}`:'vacía';const progress=clamp(data.harvest/3*100,0,100);$('questProgress').style.width=progress+'%';$('questCount').textContent=data.questDone?'¡Completado!':`${Math.min(data.harvest,3)} / 3`;$('questTitle').textContent=data.questDone?'Cena compartida':'Una primera cosecha';$('questDesc').textContent=data.questDone?'El cuervo dejó una bolsita de monedas junto a la puerta. ¡Qué buena noche!':'Cultiva y recoge 3 nabos lunares para la cena.';if(data.questDone){$('questCount').classList.add('taskdone')}
}
function rgb(hex){return hex}
function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h))}
function line(x1,y1,x2,y2,c,w=1){ctx.strokeStyle=c;ctx.lineWidth=w;ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke()}
function rng(x,y){let v=Math.sin(x*127.1+y*311.7+17.3)*43758.5453;return v-Math.floor(v)}
function drawGround(t){let night=(t>.55?clamp((t-.55)*1.6,0,.62):0);rect(0,0,768,512,'#304b3d');for(let y=0;y<H;y++)for(let x=0;x<W;x++){let r=rng(x,y),c=r>.82?'#395744':r<.13?'#2d4739':'#34513f';rect(x*T,y*T,T,T,c);if(r>.6){rect(x*T+5+(r*15|0),y*T+7,T*.11,T*.11,'#82916a');rect(x*T+22,y*T+20,T*.09,T*.09,'#263f35')}}
// meandering pebble path
for(let x=0;x<24;x++){let yy=13+Math.sin(x*.45)*.55;for(let y=Math.floor(yy)-1;y<Math.floor(yy)+2;y++){if(y>=0&&y<16){rect(x*T,y*T,T,T,'#796c54');let v=rng(x+44,y+8);if(v>.35){rect(x*T+4+v*15,y*T+8+v*9,4,3,v>.7?'#a49369':'#655b49')}}}}
// distant hedges
for(let x=0;x<24;x++){if(x>4&&x<15)continue;let y=3+(rng(x,3)*2|0);rect(x*T,y*T,31,20,'#253f36');rect(x*T+2,y*T-5,26,13,'#416148');rect(x*T+5,y*T-8,20,8,'#55704e')}
// water pond left
rect(29,176,112,72,'#233c3c');rect(35,181,99,59,'#527c77');rect(42,186,79,45,'#609088');rect(52,192,25,3,'#9ab59a');rect(91,211,25,3,'#8eaa91');rect(37,235,99,9,'#66734b');rect(24,245,118,9,'#4d6046');
// shed right upper
rect(535,100,147,105,'#403d32');rect(545,114,127,81,'#9a7350');rect(530,104,158,17,'#443e35');rect(542,92,139,14,'#63503b');rect(552,124,111,8,'#b88d5b');rect(554,140,38,53,'#544738');rect(603,141,52,37,'#273b3a');rect(609,146,40,25,'#98a489');rect(617,147,3,23,'#627665');rect(630,146,3,24,'#627665');rect(570,149,6,6,'#edc473');rect(560,191,25,5,'#c29b67');
// little fence around bed
for(let x=5;x<15;x++){if(x!==10&&x!==11){rect(x*T+4,188,24,5,'#c4a26c');rect(x*T+6,183,5,13,'#9a7951');rect(x*T+22,183,5,13,'#9a7951')}}for(let y=6;y<12;y++){rect(162,y*T+4,5,24,'#c4a26c');rect(157,y*T+5,13,5,'#9a7951');rect(157,y*T+22,13,5,'#9a7951');rect(445,y*T+4,5,24,'#c4a26c');rect(441,y*T+5,13,5,'#9a7951');rect(441,y*T+22,13,5,'#9a7951')}
// old apple tree + apples
rect(695,227,14,73,'#68513c');rect(684,245,13,14,'#68513c');rect(704,253,13,13,'#68513c');rect(667,194,61,44,'#34543e');rect(677,180,48,38,'#456847');rect(687,174,31,29,'#55764c');for(const [ax,ay] of [[680,205],[704,191],[716,216]]){rect(ax,ay,6,7,'#c85b4b');rect(ax+2,ay-2,3,2,'#829257')}
// moon & stars
rect(687,31,27,27,'#f1d991');rect(679,27,27,27,'#304b3d');for(const [sx,sy] of [[74,43],[172,71],[312,35],[484,56],[577,34],[749,90],[462,140],[199,151]]){rect(sx,sy,3,3,'#eddfaa');if(rng(sx,sy)>.4)rect(sx-2,sy+1,7,1,'#a8b48a')}
if(night>0){rect(0,0,768,512,`rgba(17,25,47,${night})`)} }
function drawPlot(){for(const p of plots){let x=p.x*T,y=p.y*T;rect(x,y,T,T,p.tilled?'#75553d':'#3e5b42');if(p.tilled){rect(x+3,y+4,26,24,p.watered?'#493d37':'#654831');for(let i=0;i<3;i++){rect(x+5,y+7+i*7,22,2,p.watered?'#665448':'#806044')}if(p.watered){rect(x+4,y+4,3,3,'#6b8780');rect(x+25,y+22,3,3,'#6b8780')}}else{rect(x+2,y+2,28,28,'#456247');rect(x+4,y+4,24,24,'#3e5942')}
if(p.crop){let typ=types[p.crop],r=clamp(p.progress/typ.grow,0,1),h=7+Math.floor(r*14);rect(x+14,y+23-h,4,h,'#719053');rect(x+10,y+19-h,7,4,'#78985a');rect(x+17,y+14-h,7,4,'#88a35e');if(r<.45){rect(x+13,y+20-h,5,5,'#6d8d54')}else if(p.crop==='turnip'){rect(x+11,y+17-h,10,9,'#d7dfc3');rect(x+13,y+19-h,6,5,'#f0e9ce');rect(x+14,y+15-h,2,4,'#6a8c4c');rect(x+17,y+14-h,2,5,'#829e56')}else{rect(x+10,y+14-h,12,10,'#7b536f');rect(x+13,y+11-h,7,8,'#d49cce');rect(x+15,y+9-h,3,4,'#ebc6d9');rect(x+15,y+18-h,3,4,'#edc979')}
if(r>=1){rect(x+4,y+4,4,4,'#ffec9b');rect(x+23,y+8,3,3,'#ffec9b');rect(x+24,y+22,2,2,'#fff1ae')}}
if(selectedPlot===p){rect(x+1,y+1,30,2,'#f2d677');rect(x+1,y+29,30,2,'#f2d677');rect(x+1,y+1,2,30,'#f2d677');rect(x+29,y+1,2,30,'#f2d677')}}}
function drawPlayer(){let x=Math.round(data.player.x*T),y=Math.round(data.player.y*T);rect(x-9,y+8,19,5,'#203c31');rect(x-7,y-14,15,15,'#e6c6a2');rect(x-9,y-17,18,8,'#332b2a');rect(x-10,y-12,5,9,'#332b2a');rect(x+5,y-12,5,9,'#332b2a');rect(x-4,y-8,2,2,'#3b302b');rect(x+3,y-8,2,2,'#3b302b');rect(x-8,y+1,17,13,'#d6b957');rect(x-8,y+12,7,8,'#49564b');rect(x+2,y+12,7,8,'#49564b');rect(x-9,y+19,9,3,'#322f2c');rect(x+2,y+19,9,3,'#322f2c');rect(x-10,y+2,4,9,'#e6c6a2');rect(x+7,y+2,4,8,'#e6c6a2');rect(x-4,y+2,8,2,'#efe29e')}
function draw(){let time=(data.played%240)/240;drawGround(time);drawPlot();drawPlayer();
// floating moths
let f=performance.now()/800;for(let i=0;i<4;i++){let x=235+Math.sin(f+i*2)*8+i*57,y=128+Math.cos(f*1.3+i)*8;rect(x,y,3,3,'#f0dd91');rect(x-2,y+1,2,2,'#b9bd87')}
ctx.font='10px monospace';ctx.fillStyle='#efe5c4';ctx.fillText('✦ EL HUERTO',22,28);
let hour=18+Math.floor(time*6),minute=Math.floor((time*6%1)*60/10)*10;$('clockFill').style.width=(time*100)+'%';$('clockText').textContent=`${String(hour%24).padStart(2,'0')}:${String(minute).padStart(2,'0')}`;$('sceneTime').textContent=time<.35?'ÚLTIMA LUZ':time<.75?'ANOCHECER':'NOCHE SERENA';}

function setTool(tool){data.tool=tool;document.querySelectorAll('.tool[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool===tool));const hints={hoe:'Azada: prepara una parcela libre.',seed:`Sembrar ${types[data.selectedSeed].name}: elige una parcela arada.`,water:'Regadera: riega una semilla para que crezca.',harvest:'Cosechar: recoge los cultivos maduros.',hand:'Mano: recoge una manzana del árbol.'};$('toolHint').textContent=hints[tool]||'Toca una parcela para trabajar.'}
function act(p){if(!p){say('Acércate a una parcela del huerto.');return}selectedPlot=p;switch(data.tool){case'hoe':if(!p.tilled){p.tilled=true;say('La tierra está lista para sembrar.')}else say('Esta parcela ya está arada.');break;case'seed':if(!p.tilled){say('Primero prepara la tierra con la azada.');break}if(p.crop){say('Aquí ya está creciendo algo.');break}let key=data.selectedSeed,qty=key==='turnip'?'turnipSeeds':'flowerSeeds';if(data[qty]<=0){say('No te quedan semillas de '+types[key].name+'.');break}data[qty]--;p.crop=key;p.progress=0;p.watered=false;say(`Sembraste ${types[key].name}. Dale un poco de agua.`);break;case'water':if(!p.crop){say('No hay nada que regar aquí todavía.');break}if(p.progress>=types[p.crop].grow){say('¡Ya está lista para cosechar!');break}p.watered=true;say('Agüita fresca. La planta ya puede crecer.');break;case'harvest':if(!p.crop){say('Esta parcela está vacía.');break}if(p.progress<types[p.crop].grow){say('Todavía está creciendo. Un poco de paciencia.');break}let crop=p.crop;if(crop==='turnip')data.turnipInv++;else data.flowerInv++;data.harvest+=crop==='turnip'?1:0;p.crop=null;p.progress=0;p.watered=false;say(`¡Cosechaste ${types[crop].name}! Va a la cesta.`);if(!data.questDone&&data.harvest>=3){data.questDone=true;data.coins+=18;say('¡Encargo cumplido! +18 monedas del cuervo.')}break;case'hand':if(!p.crop){say('La parcela está en calma.');break}if(p.progress>=types[p.crop].grow){let c=p.crop;if(c==='turnip')data.turnipInv++;else data.flowerInv++;data.harvest+=c==='turnip'?1:0;p.crop=null;p.progress=0;p.watered=false;say(`¡Cosechaste ${types[c].name}!`);if(!data.questDone&&data.harvest>=3){data.questDone=true;data.coins+=18;say('¡Encargo cumplido! +18 monedas.')}}else say('La planta todavía no está lista.');break}ui();save()}
function nearestPlot(){let best=null,dist=Infinity;for(const p of plots){let d=(p.x+.5-data.player.x)**2+(p.y+.5-data.player.y)**2;if(d<dist){dist=d;best=p}}return dist<10?best:null}
canvas.addEventListener('pointerdown',e=>{const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*W*T,y=(e.clientY-r.top)/r.height*H*T;const p=plots.find(p=>x>=p.x*T&&x<(p.x+1)*T&&y>=p.y*T&&y<(p.y+1)*T);if(p){act(p);return}if(x>660&&y>170&&y<310&&data.tool==='hand'){if(data.applePickedDay===data.day){say('Hoy ya recogiste las manzanas maduras.');return}data.applePickedDay=data.day;data.appleInv+=2;ui();save();say('Dos manzanas dulces para la cesta. 🍎')}});
document.querySelectorAll('.tool[data-tool]').forEach(b=>b.addEventListener('click',()=>setTool(b.dataset.tool)));
document.querySelectorAll('.seed').forEach(b=>b.addEventListener('click',()=>{let seed=b.dataset.seed,qty=seed==='turnip'?'turnipSeeds':'flowerSeeds',price=types[seed].price;if(data[qty]===0){if(data.coins<price){say('Te faltan monedas para comprar semillas.');return}data.coins-=price;data[qty]+=3;say(`Compraste 3 semillas de ${types[seed].name}.`)}data.selectedSeed=seed;document.querySelectorAll('.seed').forEach(x=>x.classList.toggle('active',x===b));setTool('seed');ui();save()}));
$('sellBtn').addEventListener('click',()=>{let total=data.turnipInv*types.turnip.sell+data.flowerInv*types.nightflower.sell+data.appleInv*4;if(!total){say('La cesta está vacía. ¡Primero cosecha algo!');return}data.coins+=total;data.turnipInv=0;data.flowerInv=0;data.appleInv=0;ui();save();say(`¡Venta hecha! +${total} monedas. ¡Gracias, vecina!`)});
$('journalBtn').addEventListener('click',()=>$('modal').classList.add('open'));$('closeModal').addEventListener('click',()=>$('modal').classList.remove('open'));$('modal').addEventListener('click',e=>{if(e.target===$('modal'))$('modal').classList.remove('open')});
window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();let k=e.key.toLowerCase();keys[k]=true;if(k==='f')act(nearestPlot());if(k==='1')setTool('hoe');if(k==='2')setTool('seed');if(k==='3')setTool('water');if(k==='4')setTool('harvest');if(k==='5')setTool('hand');if(k==='escape')$('modal').classList.remove('open')});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);window.addEventListener('blur',()=>keys={});
function frame(now){let dt=Math.min((now-last)/1000,.08);last=now;data.played+=dt;let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0);if(dx||dy){let len=Math.hypot(dx,dy);data.player.x=clamp(data.player.x+dx/len*dt*3.1,.4,23.5);data.player.y=clamp(data.player.y+dy/len*dt*3.1,.5,15.2)}for(const p of plots){if(p.crop&&p.watered&&p.progress<types[p.crop].grow)p.progress=Math.min(types[p.crop].grow,p.progress+dt)}let day=Math.floor(data.played/240)+1;if(day>data.day){data.day=day;say('Amanece un nuevo día. Las plantas siguen creciendo.');ui();save()}if(now-dirty>5000){save();dirty=now}draw();requestAnimationFrame(frame)}
ui();setTool(data.tool);if(!localStorage.getItem('midnightGardenSave')){setTimeout(()=>say('Bienvenida a tu pequeño refugio. ¡Empieza preparando la tierra!'),500)}requestAnimationFrame(frame);
</script></body></html>

