function draw(){let time=(data.played%240)/240;drawGround(time);drawPlot();drawPlayer();let f=performance.now()/800;for(let i=0;i<4;i++){let x=235+Math.sin(f+i*2)*8+i*57,y=128+Math.cos(f*1.3+i)*8;rect(x,y,3,3,'#f0dd91');rect(x-2,y+1,2,2,'#b9bd87')}ctx.font='10px monospace';ctx.fillStyle='#efe5c4';ctx.fillText('✦ EL HUERTO',22,28);let hour=18+Math.floor(time*6),minute=Math.floor((time*6%1)*60/10)*10;$('clockFill').style.width=(time*100)+'%';$('clockText').textContent=`${String(hour%24).padStart(2,'0')}:${String(minute).padStart(2,'0')}`;$('sceneTime').textContent=time<.35?'ÚLTIMA LUZ':time<.75?'ANOCHECER':'NOCHE SERENA'}
function setTool(tool){data.tool=tool;document.querySelectorAll('.tool[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool===tool));$('toolHint').textContent=({hoe:'Azada: prepara una parcela libre.',seed:`Sembrar ${types[data.selectedSeed].name}: elige una parcela arada.`,water:'Regadera: riega una semilla para que crezca.',harvest:'Cosechar: recoge los cultivos maduros.',hand:'Mano: recoge una manzana del árbol.'})[tool]||'Toca una parcela para trabajar.'}
function finishQuest(){if(!data.questDone&&data.harvest>=3){data.questDone=true;data.coins+=18;say('¡Encargo cumplido! +18 monedas del cuervo.')}}function act(p){if(!p){say('Acércate a una parcela del huerto.');return}selectedPlot=p;let msg='';if(data.tool==='hoe'){if(p.tilled)msg='Esta parcela ya está arada.';else{p.tilled=true;msg='La tierra está lista para sembrar.'}}else if(data.tool==='seed'){if(!p.tilled)msg='Primero prepara la tierra con la azada.';else if(p.crop)msg='Aquí ya está creciendo algo.';else{let q=data.selectedSeed==='turnip'?'turnipSeeds':'flowerSeeds';if(!data[q])msg='No te quedan semillas. Compra más monedas en la cesta.';else{data[q]--;p.crop=data.selectedSeed;p.progress=0;p.watered=false;msg=`Sembraste ${types[p.crop].name}. Dale un poco de agua.`}}}else if(data.tool==='water'){if(!p.crop)msg='No hay nada que regar aquí todavía.';else if(p.progress>=types[p.crop].grow)msg='¡Ya está lista para cosechar!';else{p.watered=true;msg='Agüita fresca. La planta ya puede crecer.'}}else if(data.tool==='harvest'||data.tool==='hand'){if(!p.crop)msg='Esta parcela está vacía.';else if(p.progress<types[p.crop].grow)msg='Todavía está creciendo. Un poco de paciencia.';else{let c=p.crop;if(c==='turnip')data.turnipInv++;else data.flowerInv++;if(c==='turnip')data.harvest++;p.crop=null;p.progress=0;p.watered=false;msg=`¡Cosechaste ${types[c].name}! Va a la cesta.`;finishQuest()}}if(msg)say(msg);ui();save()}
function nearestPlot(){let best=null,dist=Infinity;for(const p of plots){let d=(p.x+.5-data.player.x)**2+(p.y+.5-data.player.y)**2;if(d<dist){dist=d;best=p}}return dist<10?best:null}
canvas.addEventListener('pointerdown',e=>{const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*W*T,y=(e.clientY-r.top)/r.height*H*T,p=plots.find(p=>x>=p.x*T&&x<(p.x+1)*T&&y>=p.y*T&&y<(p.y+1)*T);if(p){act(p);return}if(x>660&&y>170&&y<310&&data.tool==='hand'){if(data.applePickedDay===data.day){say('Hoy ya recogiste las manzanas maduras.');return}data.applePickedDay=data.day;data.appleInv+=2;ui();save();say('Dos manzanas dulces para la cesta. 🍎')}});

